"""Generate packaged catalogs from the observed reference; never edit generated files."""
import argparse
import json
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument('--source', type=Path, required=True)
parser.add_argument('--ai-project', type=Path, required=True)
parser.add_argument('--check', action='store_true')
args = parser.parse_args()
catalog = json.loads(args.source.read_text(encoding='utf-8-sig'))
for group, count in [('categories', 18), ('locations', 12), ('id_types', 3)]:
    rows = catalog[group]
    assert len(rows) == count and len({r['id'] for r in rows}) == count
    assert len({r['source_label'] for r in rows}) == count
root = Path(__file__).resolve().parents[1]
q = lambda s: json.dumps(s, ensure_ascii=False)
code = 'package com.example.app_1.ui.screens\n\n// GENERATED by scripts/sync_chala_catalog.py. Source: design/chala_catalog.json\n'
code += 'internal data class CatalogEntry(val id: String, val sourceLabel: String, val displayLabel: String)\n'
code += 'internal object ChalaCatalog {\n    const val version = ' + q(catalog['version']) + '\n'
for group, name in [('categories', 'categories'), ('locations', 'locations'), ('id_types', 'idTypes')]:
    code += f'    val {name} = listOf(\n'
    code += ''.join('        CatalogEntry(' + ', '.join(q(r[k]) for k in ['id','source_label','display_label']) + '),\n' for r in catalog[group])
    code += '    )\n'
code += '''    fun resolve(entries: List<CatalogEntry>, value: String): CatalogEntry? =
        entries.firstOrNull { value == it.id || value == it.sourceLabel || value == it.displayLabel }
}
'''
outputs = {
    root / 'app/src/main/java/com/example/app_1/ui/screens/ChalaCatalog.kt': code,
    args.ai_project / 'matching_system/chala_catalog.json': json.dumps(catalog, indent=2, ensure_ascii=False) + '\n',
}
for path, content in outputs.items():
    if args.check:
        assert path.read_text(encoding='utf-8') == content, f'Stale catalog: {path}'
    else:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding='utf-8')
print('Catalog verified: 18 categories, 12 locations, 3 ID types')
